class Solution { public: string makeLargestSpecial(string s){vector<string> blocks;int balance=0,start=0;for(int i=0;i<(int)s.size();++i){balance+=s[i]=='1'?1:-1;if(balance==0){blocks.push_back("1"+makeLargestSpecial(s.substr(start+1,i-start-1))+"0");start=i+1;}}sort(blocks.rbegin(),blocks.rend());return accumulate(blocks.begin(),blocks.end(),string());} };
